import mongoose, { Schema } from 'mongoose';
const item = new Schema({ product: { type: Schema.Types.ObjectId, ref: 'Product', required: true }, variantId: { type: Schema.Types.ObjectId, required: true }, name: String, slug: String, sku: String, size: String, color: String, image: String, unitPrice: Number, quantity: Number, lineTotal: Number }, { _id: false });
const schema = new Schema({ reference: { type: String, unique: true, index: true }, idempotencyKey: { type: String, unique: true, index: true }, customer: { name: String, phone: String, address: String, city: String, notes: String }, items: [item], subtotal: Number, deliveryFee: Number, total: Number, currency: String, whatsappMessage: String, whatsappState: { type: String, enum: ['link_created', 'owner_confirmed'], default: 'link_created' }, status: { type: String, enum: ['pending_whatsapp', 'confirmed', 'processing', 'shipped', 'delivered', 'cancelled'], default: 'pending_whatsapp', index: true }, stockApplied: { type: Boolean, default: false }, adminNotes: String }, { timestamps: true });
export const Order = mongoose.model('Order', schema);
